tugas menyusul benar","ops":[{"op":"set","path":["petugas",3,"nama"],"value":""},{"op":"set","path":["petugas",3,"menyusul"],"value":true}],"galat":[],"status":"draf"},{"nama":"petugas menyusul bukan boolean","ops":[{"op":"set","path":["petugas",0,"menyusul"],"value":"ya"}],"galat":["Petugas 1: penanda menyusul harus ya atau tidak"]},{"nama":"petugas baru bukan boolean","ops":[{"op":"set","path":["petugas",0,"baru"],"value":"ya"}],"galat":["Petugas 1: penanda baru harus ya atau tidak"]},{"nama":"petugas peran asing","ops":[{"op":"set","path":["petugas",0,"peran"],"value":"tukang"}],"galat":["Petugas 1: peran tidak dikenal"]},{"nama":"petugas tanpa peran lapangan","ops":[{"op":"set","path":["petugas",0,"peran"],"value":""}],"galat":[],"status":"draf"},{"nama":"petugas status asing","ops":[{"op":"set","path":["petugas",0,"status"],"value":"Magang"}],"galat":["Petugas 1: status harus Organik atau Mitra"]},{"nama":"petugas mitra tanpa sumber","ops":[{"op":"set","path":["petugas",1,"sumber"],"value":""}],"galat":["Petugas 2: sumber mitra wajib dipilih (kepka atau seleksi)"]},{"nama":"petugas organik dengan sumber","ops":[{"op":"set","path":["petugas",0,"sumber"],"value":"kepka"}],"galat":["Petugas 1: sumber mitra hanya untuk mitra"]},{"nama":"petugas sumber asing","ops":[{"op":"set","path":["petugas",1,"sumber"],"value":"titipan"}],"galat":["Petugas 2: sumber mitra tidak dikenal"]},{"nama":"petugas jabatan asing","ops":[{"op":"set","path":["petugas",0,"jabatan"],"value":["ketua","bos"]}],"galat":["Petugas 1: jabatan tidak dikenal"]},{"nama":"petugas jabatan dobel","ops":[{"op":"set","path":["petugas",0,"jabatan"],"value":["ketua","ketua"]}],"galat":["Petugas 1: jabatan tidak dikenal"]},{"nama":"petugas jabatan bukan daftar","ops":[{"op":"set","path":["petugas",0,"jabatan"],"value":"ketua"}],"galat":["Petugas 1: jabatan tidak dikenal"]},{"nama":"petugas nama dobel beda huruf","ops":[{"op":"set","path":["petugas",3,"nama"],"value":"  dedi kurnia "},{"op":"set","path":["petugas",2,"nama"],"value":"DEDI KURNIA"}],"galat":["Nama petugas dobel: dedi kurnia"]},{"nama":"petugas kurang satu (jumlah tidak sama)","ops":[{"op":"del","path":["petugas",3]}],"galat":[],"status":"draf"},{"nama":"petugas lebih satu (jumlah tidak sama)","ops":[{"op":"tambah","path":["petugas"],"value":{"id":"p5","nama":"Eka Sari","menyusul":false,"peran":"ppl","status":"Mitra","sumber":"kepka","baru":false,"jabatan":[]}}],"galat":[],"status":"draf"},{"nama":"petugas tim tanpa peran lapangan tambahan","ops":[{"op":"tambah","path":["petugas"],"value":{"id":"p5","nama":"Eka Sari","menyusul":false,"peran":"","status":"Organik","sumber":"","baru":false,"jabatan":["wakil"]}}],"galat":[],"status":"final"},{"nama":"tanpa kelas dan tanpa peran","ops":[{"op":"set","path":["kelas"],"value":[]},{"op":"set","path":["peran","pml","on"],"value":false},{"op":"set","path":["peran","ppl","on"],"value":false},{"op":"set","path":["petugas"],"value":[]}],"galat":[],"status":"draf"},{"nama":"tanpa kelas tetapi ada peran","ops":[{"op":"set","path":["kelas"],"value":[]}],"galat":[],"status":"final"},{"nama":"kunci kelas dan petugas tidak ada","ops":[{"op":"del","path":["kelas"]},{"op":"del","path":["petugas"]}],"galat":[],"status":"draf"}]}'::jsonb;
  base jsonb; admin bigint := 354; z bigint; ab bigint; ap bigint; ro text := '2906.BMA.001'; ro2 text := '2906.BMA.002'; ia bigint; ib bigint; id2 bigint;
  r jsonb; isi2 jsonb; pid bigint; pid2 bigint; st text; lm bigint; n int;
begin
  perform set_config('app.akun_id', '', true);
  base := vek -> 'base';
  insert into keu_master_peran(kode, nama, lingkup, urut) values ('BEND', 'Bendahara', 'global', 6), ('PBJ', 'PBJ', 'ro', 7) on conflict do nothing;
  select id into z from sigap_akun where aktif and id <> admin and not exists (select 1 from keu_penugasan t where t.akun_id = sigap_akun.id and t.dibatalkan_at is null) order by id limit 1;
  select id into ab from sigap_akun where aktif and id not in (admin, z) order by id limit 1;
  select id into ap from sigap_akun where aktif and id not in (admin, z, ab) order by id limit 1;
  insert into keu_penugasan(akun_id, peran_kode, ro_kode, berlaku_mulai) values (ab, 'BEND', null, '2026-01-01'), (ap, 'PBJ', ro, '2026-01-01');

  -- ===== penerima =====
  perform pg_temp.ok(array(select keu_penerima(array['BEND'], ro)) = array[ab], 'penerima BEND');
  perform pg_temp.ok(array(select keu_penerima(array['PBJ'], ro) order by 1) = array(select x from unnest(array[ap]) x order by 1), 'penerima PBJ pada RO yang punya PBJ');
  perform pg_temp.ok(array(select keu_penerima(array['PBJ'], ro2)) = array[admin], 'PBJ dialihkan ke PPK bila RO tidak punya PBJ');
  perform pg_temp.ok(array(select keu_penerima(array['KPA','PPK','TU'], ro)) = array[admin], 'penerima KPA, PPK, TU dedup');
  perform pg_temp.ok(array(select keu_penerima(array['XXX'], ro)) = array[]::bigint[], 'peran tak dikenal: kosong');

  -- ===== bahan =====
  insert into keu_ident(tahun, ro_kode, nama, status, ver, form, dibuat_oleh) values (2026, ro, 'UJI notif A', 'sah', 1, pg_temp.frm('UJI notif A', 'Triwulan IV'), admin) returning id into ia;
  insert into keu_ident_versi(ident_id, ver, form) values (ia, 1, pg_temp.frm('UJI notif A', 'Triwulan IV'));
  insert into keu_ident(tahun, ro_kode, nama, status, ver, form, dibuat_oleh) values (2026, ro, 'UJI notif B', 'sah', 1, pg_temp.frm('UJI notif B', 'Triwulan I'), admin) returning id into ib;
  insert into keu_ident_versi(ident_id, ver, form) values (ib, 1, pg_temp.frm('UJI notif B', 'Triwulan I'));
  insert into keu_ident(tahun, ro_kode, nama, status, ver, form, dibuat_oleh) values (2026, ro2, 'UJI notif D', 'sah', 1, pg_temp.frm('UJI notif D', 'Triwulan IV'), admin) returning id into id2;
  insert into keu_ident_versi(ident_id, ver, form) values (id2, 1, pg_temp.frm('UJI notif D', 'Triwulan IV'));

  -- ===== A (sebelum H-15): Draf tidak memberi notifikasi; Final memberi ident_fix; nama terisi memberi nama_terisi =====
  isi2 := jsonb_set(jsonb_set(base, '{petugas,3,nama}', '""'), '{petugas,3,menyusul}', 'true');
  perform keu_jalankan(admin, 'keu_lanjutan_simpan', jsonb_build_object('p_ident', ia, 'p_isi', isi2));
  perform pg_temp.ok((select count(*) = 0 from keu_notifikasi where ident_id = ia), 'Draf: tanpa notifikasi');
  perform pg_temp.ok((select count(*) = 0 from keu_pengecualian where ident_id = ia), 'sebelum H-15: tanpa keputusan KPA');
  perform keu_jalankan(admin, 'keu_lanjutan_simpan', jsonb_build_object('p_ident', ia, 'p_isi', base));
  perform pg_temp.ok((select array_agg(akun_id order by akun_id) from keu_notifikasi where ident_id = ia and jenis = 'ident_fix') = (select array_agg(x order by x) from unnest(array[admin, ab, ap]) x), 'ident_fix ke PPK/TU/KPA, Bendahara, dan PBJ');
  perform pg_temp.ok((select array_agg(akun_id) from keu_notifikasi where ident_id = ia and jenis = 'nama_terisi') = array[admin], 'nama_terisi ke PPK');
  perform pg_temp.ok((select count(*) = 0 from keu_notifikasi where ident_id = ia and jenis = 'ident_pasca_h15'), 'sebelum H-15: tanpa notifikasi pasca');
  -- Final -> Final (ubah wilayah) tidak mengirim ident_fix lagi
  perform keu_jalankan(admin, 'keu_lanjutan_simpan', jsonb_build_object('p_ident', ia, 'p_isi', jsonb_set(base, '{wilayah}', '"Nagari X"')));
  perform pg_temp.ok((select count(*) = 3 from keu_notifikasi where ident_id = ia and jenis = 'ident_fix'), 'ident_fix hanya saat bergeser dari Draf');

  -- ===== D (RO tanpa PBJ): ident_fix ke PPK menggantikan PBJ, Bendahara tetap =====
  perform keu_jalankan(admin, 'keu_lanjutan_simpan', jsonb_build_object('p_ident', id2, 'p_isi', base));
  perform pg_temp.ok((select array_agg(akun_id order by akun_id) from keu_notifikasi where ident_id = id2 and jenis = 'ident_fix') = (select array_agg(x order by x) from unnest(array[admin, ab]) x), 'RO tanpa PBJ: PPK menggantikan, PBJ lain tidak diberi tahu');

  -- ===== B (sesudah H-15): keputusan KPA otomatis + notifikasi KPA dan PPK =====
  perform keu_jalankan(admin, 'keu_lanjutan_simpan', jsonb_build_object('p_ident', ib, 'p_isi', base));
  perform pg_temp.ok((select count(*) = 1 and bool_and(otomatis) and bool_and(status = 'diajukan') and max(lanjutan_ver) = 1 from keu_v_pengecualian where ident_id = ib and jenis = 'perubahan_h15'), 'versi 1 sesudah H-15: keputusan KPA diajukan otomatis');
  perform pg_temp.ok((select count(*) = 0 from keu_notifikasi where ident_id = ib and jenis = 'ident_fix'), 'sesudah H-15 tidak mengirim ident_fix');
  perform pg_temp.ok((select count(*) = 1 and min(akun_id) = admin from keu_notifikasi where ident_id = ib and jenis = 'ident_pasca_h15'), 'ident_pasca_h15 ke KPA dan PPK (satu akun)');
  perform keu_jalankan(admin, 'keu_lanjutan_simpan', jsonb_build_object('p_ident', ib, 'p_isi', jsonb_set(base, '{wilayah}', '"Nagari Y"'), 'p_alasan', 'Wilayah tugas bertambah satu nagari'));
  perform pg_temp.ok((select count(*) = 2 from keu_pengecualian where ident_id = ib and jenis = 'perubahan_h15'), 'tiap versi sesudah H-15 punya keputusan sendiri');
  perform pg_temp.ok((select alasan like 'Wilayah tugas bertambah%' from keu_pengecualian where ident_id = ib and lanjutan_ver = 2), 'alasan versi terbawa');
  -- simpan tanpa perubahan tidak membuat keputusan baru
  perform keu_jalankan(admin, 'keu_lanjutan_simpan', jsonb_build_object('p_ident', ib, 'p_isi', jsonb_set(base, '{wilayah}', '"Nagari Y"')));
  perform pg_temp.ok((select count(*) = 2 from keu_pengecualian where ident_id = ib and jenis = 'perubahan_h15'), 'isi sama: tanpa keputusan baru');

  -- ===== keputusan KPA =====
  select id into pid from keu_pengecualian where ident_id = ib and lanjutan_ver = 1 and jenis = 'perubahan_h15';
  perform pg_temp.gagal(format($q$select keu_jalankan(%s, 'keu_pengecualian_putus', %L::jsonb)$q$, z, jsonb_build_object('p_id', pid, 'p_setuju', true)::text), '42501');
  perform pg_temp.gagal(format($q$select keu_jalankan(%s, 'keu_pengecualian_putus', %L::jsonb)$q$, ab, jsonb_build_object('p_id', pid, 'p_setuju', true)::text), '42501'); -- Bendahara bukan KPA
  perform pg_temp.gagal(format($q$select keu_jalankan(%s, 'keu_pengecualian_putus', %L::jsonb)$q$, admin, jsonb_build_object('p_id', pid, 'p_setuju', false, 'p_catatan', 'no')::text), '23514');
  perform pg_temp.gagal(format($q$select keu_jalankan(%s, 'keu_pengecualian_putus', %L::jsonb)$q$, admin, jsonb_build_object('p_id', 999999, 'p_setuju', true)::text), '23514');
  perform pg_temp.gagal(format($q$select keu_jalankan(%s, 'keu_pengecualian_putus', %L::jsonb)$q$, admin, jsonb_build_object('p_id', pid)::text), '22023');
  st := keu_jalankan(admin, 'keu_pengecualian_putus', jsonb_build_object('p_id', pid, 'p_setuju', true, 'p_catatan', 'Disetujui, penambahan nagari sah')) #>> '{}';
  perform pg_temp.ok(st = 'disetujui' and (select status = 'disetujui' and diputus_oleh_nama is not null and diputus_at is not null from keu_v_pengecualian where id = pid), 'KPA menyetujui');
  perform pg_temp.gagal(format($q$select keu_jalankan(%s, 'keu_pengecualian_putus', %L::jsonb)$q$, admin, jsonb_build_object('p_id', pid, 'p_setuju', false, 'p_catatan', 'berubah pikiran')::text), '23514'); -- sudah diputus
  perform pg_temp.ok((select count(*) >= 1 from keu_notifikasi where pengecualian_id = pid and jenis = 'pengecualian_putus'), 'pengaju dan PPK diberi tahu keputusan');
  perform pg_temp.ok((select count(*) = 1 from keu_ident_riwayat where ident_id = ib and aksi = 'pengecualian'), 'keputusan tercatat di riwayat identifikasi');
  select id into pid2 from keu_pengecualian where ident_id = ib and lanjutan_ver = 2 and jenis = 'perubahan_h15';
  perform pg_temp.gagal(format($q$select keu_jalankan(%s, 'keu_pengecualian_tarik', %L::jsonb)$q$, admin, jsonb_build_object('p_id', pid2)::text), '23514'); -- otomatis tidak dapat ditarik
  st := keu_jalankan(admin, 'keu_pengecualian_putus', jsonb_build_object('p_id', pid2, 'p_setuju', false, 'p_catatan', 'Perlu dokumen pendukung')) #>> '{}';
  perform pg_temp.ok(st = 'ditolak', 'KPA menolak dengan catatan');
  -- versi tetap terbaca modul hilir walau ditolak (tidak memblokir)
  perform pg_temp.ok((select lanjutan_ver = 2 and lanjutan_ada and sumber = 'lanjutan' from keu_v_ident_acuan where ident_id = ib), 'ditolak tidak memblokir pemakaian versi');

  -- ===== pengecualian manual =====
  perform pg_temp.gagal(format($q$select keu_jalankan(%s, 'keu_pengecualian_ajukan', %L::jsonb)$q$, z, jsonb_build_object('p_ident', ia, 'p_jenis', 'kebijakan', 'p_objek', 'Kelas melebihi batas', 'p_alasan', 'Peserta tambahan dari kecamatan lain')::text), '42501');
  perform pg_temp.gagal(format($q$select keu_jalankan(%s, 'keu_pengecualian_ajukan', %L::jsonb)$q$, admin, jsonb_build_object('p_ident', ia, 'p_jenis', 'perubahan_h15', 'p_objek', 'Kelas melebihi batas', 'p_alasan', 'Peserta tambahan dari kecamatan lain')::text), '22023');
  perform pg_temp.gagal(format($q$select keu_jalankan(%s, 'keu_pengecualian_ajukan', %L::jsonb)$q$, admin, jsonb_build_object('p_ident', ia, 'p_jenis', 'kebijakan', 'p_objek', 'Kelas melebihi batas', 'p_alasan', 'pendek')::text), '23514');
  perform pg_temp.gagal(format($q$select keu_jalankan(%s, 'keu_pengecualian_ajukan', %L::jsonb)$q$, admin, jsonb_build_object('p_ident', ia, 'p_jenis', 'kebijakan', 'p_objek', 'ab', 'p_alasan', 'Peserta tambahan dari kecamatan lain')::text), '23514');
  perform pg_temp.gagal(format($q$select keu_jalankan(%s, 'keu_pengecualian_ajukan', %L::jsonb)$q$, admin, jsonb_build_object('p_ident', 999999, 'p_jenis', 'kebijakan', 'p_objek', 'Kelas melebihi batas', 'p_alasan', 'Peserta tambahan dari kecamatan lain')::text), '23514');
  pid := (keu_jalankan(admin, 'keu_pengecualian_ajukan', jsonb_build_object('p_ident', ia, 'p_jenis', 'kebijakan', 'p_objek', 'Kelas melebihi batas peserta', 'p_alasan', 'Peserta tambahan dari kecamatan lain')) #>> '{}')::bigint;
  perform pg_temp.ok((select status = 'diajukan' and not otomatis and jenis = 'kebijakan' and lanjutan_ver is not null from keu_v_pengecualian where id = pid), 'pengecualian manual diajukan');
  perform pg_temp.ok((select count(*) = 1 from keu_notifikasi where pengecualian_id = pid and jenis = 'pengecualian_diajukan' and akun_id = admin), 'KPA diberi tahu pengajuan');
  perform pg_temp.gagal(format($q$select keu_jalankan(%s, 'keu_pengecualian_ajukan', %L::jsonb)$q$, admin, jsonb_build_object('p_ident', ia, 'p_jenis', 'kebijakan', 'p_objek', ' kelas melebihi batas peserta ', 'p_alasan', 'Peserta tambahan dari kecamatan lain')::text), '23514'); -- ganda
  perform pg_temp.gagal(format($q$select keu_jalankan(%s, 'keu_pengecualian_tarik', %L::jsonb)$q$, ab, jsonb_build_object('p_id', pid)::text), '42501');
  st := keu_jalankan(admin, 'keu_pengecualian_tarik', jsonb_build_object('p_id', pid)) #>> '{}';
  perform pg_temp.ok(st = 'ditarik', 'pengaju menarik');
  perform pg_temp.gagal(format($q$select keu_jalankan(%s, 'keu_pengecualian_tarik', %L::jsonb)$q$, admin, jsonb_build_object('p_id', pid)::text), '23514');
  pid := (keu_jalankan(admin, 'keu_pengecualian_ajukan', jsonb_build_object('p_ident', ia, 'p_jenis', 'rangkap', 'p_objek', 'Rangkap PJ pengolahan dan PJ kualitas', 'p_alasan', 'Jumlah pegawai terbatas pada survei ini')) #>> '{}')::bigint;
  perform keu_jalankan(admin, 'keu_pengecualian_putus', jsonb_build_object('p_id', pid, 'p_setuju', true));
  perform pg_temp.ok((select status = 'disetujui' from keu_v_pengecualian where id = pid), 'KPA menyetujui rangkap tanpa catatan');

  -- ===== baca notifikasi =====
  r := keu_jalankan(ab, 'keu_notifikasi_saya', '{}'::jsonb);
  perform pg_temp.ok((r ->> 'belum')::int = 2 and jsonb_array_length(r -> 'daftar') = 2, 'Bendahara hanya melihat notifikasinya sendiri (A dan D)');
  r := keu_jalankan(admin, 'keu_notifikasi_saya', jsonb_build_object('p_belum', true, 'p_batas', 3));
  perform pg_temp.ok(jsonb_array_length(r -> 'daftar') = 3 and (r ->> 'belum')::int > 3, 'batas daftar dihormati, jumlah belum dibaca utuh');
  perform pg_temp.ok((r -> 'daftar' -> 0 ->> 'id')::bigint > (r -> 'daftar' -> 1 ->> 'id')::bigint, 'terbaru dahulu');
  n := (keu_jalankan(ab, 'keu_notifikasi_tandai', jsonb_build_object('p_id', (r -> 'daftar' -> 0 ->> 'id')::bigint)) #>> '{}')::int;
  perform pg_temp.ok(n = 0, 'tidak dapat menandai notifikasi orang lain');
  perform pg_temp.ok(((keu_jalankan(admin, 'keu_notifikasi_saya', '{}'::jsonb)) ->> 'belum')::int = (r ->> 'belum')::int, 'notifikasi Admin tidak berubah');
  n := (keu_jalankan(admin, 'keu_notifikasi_tandai', jsonb_build_object('p_id', (r -> 'daftar' -> 0 ->> 'id')::bigint)) #>> '{}')::int;
  perform pg_temp.ok(n = 1 and ((keu_jalankan(admin, 'keu_notifikasi_saya', '{}'::jsonb)) ->> 'belum')::int = (r ->> 'belum')::int - 1, 'menandai satu');
  n := (keu_jalankan(admin, 'keu_notifikasi_tandai', '{}'::jsonb) #>> '{}')::int;
  perform pg_temp.ok(n >= 1 and ((keu_jalankan(admin, 'keu_notifikasi_saya', '{}'::jsonb)) ->> 'belum')::int = 0, 'menandai semua');

  -- ===== lembar kebijakan menunggu pengesahan =====
  perform set_config('app.akun_id', '', true);
  insert into keu_kebijakan_lembar(tahun, ver, status, isi, dibuat_oleh) values (2026, 91, 'draf', '{}'::jsonb, admin) returning id into lm;
  insert into keu_kebijakan_pengesah(lembar_id, peran_kode, akun_id) values (lm, 'KETUA', admin), (lm, 'PPK', ab), (lm, 'KPA', ap);
  update keu_kebijakan_lembar set status = 'menunggu', diajukan_oleh = admin, tanggal_rapat = date '2026-10-20', nomor_notulen = 'N-01' where id = lm;
  perform pg_temp.ok((select array_agg(akun_id order by akun_id) from keu_notifikasi where lembar_id = lm and jenis = 'lembar_menunggu') = (select array_agg(x order by x) from unnest(array[admin, ab, ap]) x), 'setiap pengesah diberi tahu');
  update keu_kebijakan_lembar set status = 'draf' where id = lm;
  update keu_kebijakan_lembar set status = 'menunggu' where id = lm;
  perform pg_temp.ok((select count(*) = 6 from keu_notifikasi where lembar_id = lm), 'pengajuan ulang mengirim lagi');

  -- ===== tulis langsung ditutup =====
  perform set_config('app.akun_id', admin::text, true);
  perform pg_temp.gagal(format('update keu_notifikasi set dibaca_at = null where akun_id = %s', admin), '42501');
  perform pg_temp.gagal('delete from keu_notifikasi', '42501');
  perform pg_temp.gagal(format('insert into keu_notifikasi(akun_id, jenis, judul) values (%s, %L, %L)', admin, 'ident_fix', 'palsu'), '42501');
  perform pg_temp.gagal(format('update keu_pengecualian set status = %L where id = %s', 'disetujui', pid2), '42501');
  perform pg_temp.gagal('delete from keu_pengecualian', '42501');
  perform set_config('app.akun_id', '', true);
  -- cek tabel: putusan tanpa pemutus tidak sah
  perform pg_temp.gagal(format('update keu_pengecualian set status = %L, diputus_oleh = null where id = %s', 'disetujui', pid2), '23514');

  -- ===== pintu hilir =====
  perform pg_temp.ok((select count(*) = 3 from keu_v_ident_acuan where ident_id in (ia, ib, id2)), 'pintu hilir memuat identifikasi sah');
  perform pg_temp.ok((select form_sah ->> 'nama' = 'UJI notif A' and lanjutan_status = 'final' and lanjutan_isi ->> 'wilayah' = 'Nagari X' from keu_v_ident_acuan where ident_id = ia), 'acuan memuat form sah dan lanjutan terbaru');
  insert into keu_ident(tahun, ro_kode, nama, status, ver, form, dibuat_oleh) values (2026, ro, 'UJI notif E', 'sah', 1, pg_temp.frm('UJI notif E', 'Triwulan IV'), admin);
  insert into keu_ident_versi(ident_id, ver, form) select id, 1, pg_temp.frm('UJI notif E', 'Triwulan IV') from keu_ident where nama = 'UJI notif E';
  perform pg_temp.ok((select not lanjutan_ada and sumber = 'awal' and lanjutan_isi is null from keu_v_ident_acuan where nama = 'UJI notif E'), 'tanpa lanjutan: sumber awal');
  insert into keu_ident(tahun, ro_kode, nama, status, ver, form, dibuat_oleh) values (2026, ro, 'UJI notif F', 'draf', 0, pg_temp.frm('UJI notif F', 'Triwulan IV'), admin);
  perform pg_temp.ok((select count(*) = 0 from keu_v_ident_acuan where nama = 'UJI notif F'), 'identifikasi belum sah tidak masuk pintu hilir');
  raise notice 'LULUS 52';
end $$;
rollback;
